package com.food.entity;
import jakarta.persistence.*;
@Entity @Table(name="menu_items") public class MenuItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private int id; @Column(name="item_name") private String itemName; private double price; private boolean available; @ManyToOne @JoinColumn(name="restaurant_id") private Restaurant restaurant; public MenuItem(){} public MenuItem(String itemName,double price,boolean available){this.itemName=itemName;this.price=price;this.available=available;} public int getId(){return id;} public void setId(int id){this.id=id;} public String getItemName(){return itemName;} public void setItemName(String itemName){this.itemName=itemName;} public double getPrice(){return price;} public void setPrice(double price){this.price=price;} public boolean isAvailable(){return available;} public void setAvailable(boolean available){this.available=available;} public Restaurant getRestaurant(){return restaurant;} public void setRestaurant(Restaurant restaurant){this.restaurant=restaurant;} }
